import { PageEvidence } from '../types/evaluation';
import { askModel, object, array, str, num } from './ollamaService';

export interface StudentReading {
  headerText: string;
  questions: PageEvidence['questions'];
  warnings: string[];
}
// The model returns boundaries only. Student work is always copied from the
// completed OCR in code, never regenerated by a second model request.
export async function organiseStudentText(
  transcript: string,
  page: number,
  knownIds: string[] = [],
): Promise<StudentReading> {
  const result: StudentReading = {headerText: '', questions: [], warnings: []};
  const lines = transcript.split('\n');
  // Bound each request without splitting or throwing away an individual line.
  const chunks: string[][] = [];
  let chunk: string[] = [];
  let size = 0;
  for (const line of lines) {
    if (chunk.length && (chunk.length >= 30 || size + line.length > 4000)) {
      chunks.push(chunk); chunk = []; size = 0;
    }
    chunk.push(line); size += line.length + 1;
  }
  if (chunk.length) chunks.push(chunk);
  for (let index = 0; index < chunks.length; index++) {
    const source = chunks[index];
    try {
      if (source.join('\n').length > 6000) throw new Error('A transcription line exceeds the mapping budget.');
      const data = await askModel<{labels: {line: number; questionId: string}[]}>(
        `Locate question boundaries in these numbered transcription lines. Return ONLY labels with the starting line and main questionId (e.g. 20), not the student text. Use unknown for unlabelled continuation, headings or ambiguous numbering; never infer a question from its answer or treat calculation step numbers as question numbers. First label MUST start at line 1. Add a label only when the question changes. Line numbers are 1-based and local to this chunk. ${knownIds.length ? 'Allowed main question ids: ' + knownIds.join(', ') + '.' : ''}\nLINES:\n${source.map((s,i) => `${i+1}: ${s}`).join('\n')}`,
        object({labels: array(object({line: num, questionId: str}))}),
        [],
        {task: `Mapping student page ${page}, text chunk ${index+1}/${chunks.length}`, maxTokens: 600, retryCompact: false},
      );
      if (!Array.isArray(data.labels) || !data.labels.length || data.labels.length > source.length || data.labels[0].line !== 1) throw new Error('Invalid question boundaries.');
      for (let i = 0; i < data.labels.length; i++) {
        const label = data.labels[i];
        if (!Number.isInteger(label.line) || label.line < 1 || label.line > source.length || (i > 0 && label.line <= data.labels[i-1].line) || typeof label.questionId !== 'string' || (label.questionId !== 'unknown' && (!/^\d+(?:\.[A-Z])?$/.test(label.questionId) || (knownIds.length > 0 && !knownIds.includes(label.questionId))))) throw new Error('Invalid or unknown question boundary.');
      }
      for (let i = 0; i < data.labels.length; i++) {
        const label = data.labels[i];
        const text = source.slice(label.line-1, i+1 < data.labels.length ? data.labels[i+1].line-1 : source.length).join('\n');
        result.questions.push({questionId: label.questionId, text, diagramDescription: /diagram|venn|figure|graph/i.test(text) ? 'See diagram evidence in transcription and source image.' : '', uncertain: label.questionId === 'unknown' || text.includes('[unclear]')});
      }
    } catch (error) {
      // A mapping failure must NEVER trigger another image read or discard OCR.
      result.questions.push({questionId:'unknown',text:source.join('\n'),diagramDescription:'',uncertain:true});
      result.warnings.push(`Page ${page}, text chunk ${index+1}: completed transcription retained but question mapping failed (${error instanceof Error ? error.message : 'invalid response'}). Teacher review required; no image was re-read.`);
    }
  }
  if (result.questions.some(q=>q.uncertain)) result.warnings.push(`Page ${page}: uncertain or unassigned text retained. Verify question labels and handwriting before finalising marks.`);
  return result;
}
